def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs chosen by seed.

    The same xs and seed must always produce the same element. The
    function must not use randomness (no random module, no os.urandom,
    no time-based state).
    """
    if not xs:
        raise ValueError("pick() requires a non-empty list")
    mask = (1 << 64) - 1
    z = (seed + 0x9E3779B97F4A7C15) & mask
    z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & mask
    z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & mask
    z ^= z >> 31
    return xs[z % len(xs)]


def test_pick_returns_member() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(50):
        assert pick(xs, seed) in xs


def test_pick_single_element() -> None:
    assert pick([7], 0) == 7
    assert pick([7], 12345) == 7


def test_pick_is_deterministic() -> None:
    xs = [3, 1, 4, 1, 5, 9, 2, 6]
    for seed in (-5, 0, 1, 42, 2**31):
        first = pick(xs, seed)
        for _ in range(5):
            assert pick(xs, seed) == first


def test_pick_varies_across_seeds() -> None:
    xs = [1, 2, 3, 4, 5, 6, 7, 8]
    seen = {pick(xs, seed) for seed in range(200)}
    assert len(seen) > 1
